<script setup>
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import UniversalChildTable from "@/components/generated/UniversalChildTable.vue";
import ErrorState from "@/components/feedback/ErrorState.vue";
import PermissionDenied from "@/components/feedback/PermissionDenied.vue";
import RecordNotFound from "@/components/feedback/RecordNotFound.vue";
import PageContainer from "@/components/layout/PageContainer.vue";
import { getDocumentDetail, getPrintFormats, getRelated, getTimeline, runDocumentAction } from "@/services/universal.js";
const route = useRoute(); const router = useRouter(); const loading = ref(true); const error = ref(null); const detail = ref(null); const timeline = ref([]); const related = ref([]); const formats = ref([]); const acting = ref(false); let controller;
const feature = computed(() => String(route.params.feature)); const name = computed(() => String(route.params.name));
const fields = computed(() => (detail.value?.metadata?.fields || []).filter((field) => !field.hidden && !["Section Break","Column Break","Tab Break","Table","Table MultiSelect","Button","HTML"].includes(field.fieldtype)));
const tables = computed(() => (detail.value?.metadata?.fields || []).filter((field) => ["Table","Table MultiSelect"].includes(field.fieldtype)));
const sections = computed(() => {
  const result = []; let current = { key: "details", title: "Details", fields: [], tables: [] };
  const push = () => { if (current.fields.length || current.tables.length) result.push(current); };
  for (const field of detail.value?.metadata?.fields || []) {
    if (field.hidden) continue;
    if (["Section Break", "Tab Break"].includes(field.fieldtype)) { push(); current = { key: field.fieldname, title: field.label || "Details", fields: [], tables: [] }; }
    else if (["Table", "Table MultiSelect"].includes(field.fieldtype)) current.tables.push(field);
    else if (!["Column Break", "Button", "HTML"].includes(field.fieldtype)) current.fields.push(field);
  }
  push(); return result;
});
async function load() { controller?.abort(); controller = new AbortController(); loading.value = true; error.value = null; try { detail.value = await getDocumentDetail(feature.value, name.value, controller.signal); const [activity, links, print] = await Promise.allSettled([getTimeline(feature.value, name.value, controller.signal), getRelated(feature.value, name.value, controller.signal), detail.value.permissions.can_print ? getPrintFormats(feature.value, name.value, controller.signal) : Promise.resolve({ formats: [] })]); timeline.value = activity.value?.records || []; related.value = links.value?.records || []; formats.value = print.value?.formats || []; } catch (caught) { if (caught.name !== "AbortError") error.value = caught; } finally { loading.value = false; } }
async function act(action) { if (acting.value || !window.confirm(`${action.label} ${name.value}?`)) return; acting.value = true; try { const result = await runDocumentAction(feature.value, name.value, action.action, detail.value.document.modified); if (result.route) await router.push(result.route); await load(); } catch (caught) { error.value = caught; } finally { acting.value = false; } }
function printDoc() { window.open(`/printview?doctype=${encodeURIComponent(detail.value.document.doctype)}&name=${encodeURIComponent(name.value)}`, "_blank", "noopener"); }
watch(() => route.fullPath, load, { immediate: true }); onBeforeUnmount(() => controller?.abort());
</script>
<template><PageContainer><PermissionDenied v-if="error?.permissionDenied" /><RecordNotFound v-else-if="error?.notFound" /><ErrorState v-else-if="error" title="Unable to load document" :message="error.message" /><div v-else-if="detail" class="ru-page"><header class="ru-page__header"><div><button class="ru-back" type="button" @click="router.push(`/generated/${feature}`)">← Back</button><span class="ru-eyebrow">GENERATED DETAIL · PROVISIONAL</span><h1>{{ detail.document[detail.metadata.title_field] || detail.document.name }}</h1><p>{{ detail.document.doctype }} · {{ detail.document.name }}</p></div><div class="ru-actions"><button v-if="detail.permissions.can_write && detail.document.docstatus === 0" class="ref-button ref-button--primary" @click="router.push(`/generated/${feature}/${encodeURIComponent(name)}/edit`)">Edit</button><button v-if="detail.permissions.can_print" @click="printDoc">Print</button><button v-for="action in detail.actions" :key="action.action" :disabled="acting" :class="{ 'ru-danger': action.destructive }" @click="act(action)">{{ action.label }}</button></div></header><section class="ru-card ru-summary"><div><span>Status</span><strong>{{ detail.document.status || ['Draft','Submitted','Cancelled'][detail.document.docstatus] }}</strong></div><div><span>Modified</span><strong>{{ detail.document.modified }}</strong></div><div><span>Owner</span><strong>{{ detail.document.owner }}</strong></div><div v-if="formats.length"><span>Print formats</span><strong>{{ formats.length }}</strong></div></section><template v-for="section in sections" :key="section.key"><section v-if="section.fields.length" class="ru-card"><h2>{{ section.title }}</h2><dl class="ru-detail-grid"><div v-for="field in section.fields" :key="field.fieldname"><dt>{{ field.label }}</dt><dd>{{ detail.document[field.fieldname] ?? '—' }}</dd></div></dl></section><UniversalChildTable v-for="table in section.tables" :key="table.fieldname" :model-value="detail.document[table.fieldname] || []" :field="table" :feature="feature" read-only /></template><section class="ru-card"><h2>Related records</h2><div v-if="!related.length" class="ru-empty">No permitted related records.</div><RouterLink v-for="record in related" :key="`${record.doctype}-${record.name}`" :to="record.route" class="ru-related">{{ record.doctype }} · {{ record.name }}</RouterLink></section><section class="ru-card"><h2>Recent activity</h2><div v-if="!timeline.length" class="ru-empty">No recent activity.</div><article v-for="event in timeline" :key="event.name" class="ru-timeline"><strong>{{ event.comment_type }}</strong><span>{{ event.content }}</span><small>{{ event.owner }} · {{ event.creation }}</small></article></section></div><div v-else class="ru-skeleton"><i v-for="n in 8" :key="n"></i></div></PageContainer></template>
